import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
from collections import Counter as C2
def solve(T):
    H,W=len(T),len(T[0])
    out=[r[:] for r in T]
    hsep={i for i,r_ in enumerate(T) if len(set(r_))==1}
    bands=[]; prev=-1
    for s in sorted(hsep)+[H]:
        if s>prev+1: bands.append((prev+1,s-1)); prev=s
    bg=C2(x for r_ in T for x in r_).most_common(1)[0][0]
    scol=T[next(iter(hsep))][0]
    vsep={j for j in range(W) if all(T[i][j]==scol for i in range(H))}
    segs=[]; cur=[]
    for j in range(W):
        if j not in vsep:
            if cur and j==cur[-1]+1: cur.append(j)
            else:
                if cur: segs.append(cur)
                cur=[j]
    if cur: segs.append(cur)
    mkc=sorted({x for r_ in T for x in r_}-{bg,scol})
    # count markers per block, then fill global-max blocks, clear markers elsewhere
    for kb,(r0,r1) in enumerate(bands):
        for cs in segs:
            n=sum(1 for i in range(r0,r1+1) for j in cs if T[i][j] in mkc)
            if n>0:
                for i in range(r0,r1+1):
                    for j in cs:
                        if T[i][j] in mkc: out[i][j]=bg
    mx=max(max(sum(1 for i in range(bands[kb][0],bands[kb][1]+1) for j in segs[sib] if T[i][j] in mkc) for sib in range(len(segs))) for kb in range(len(bands)))
    for kb,(r0,r1) in enumerate(bands):
        for sib,cs in enumerate(segs):
            n=sum(1 for i in range(r0,r1+1) for j in cs if T[i][j] in mkc)
            if n==mx:
                for i in range(r0,r1+1):
                    for j in cs: out[i][j]=mkc[0]
    return out
for p in ['Demo pair %d'%k for k in range(1,8)]:
    print(p,'MATCH' if solve(G[p+' input'])==G[p+' output'] else 'MISMATCH')
